@VisibleForTesting
protected static void applyAvailabilityZoneExpression(final List<NodeSelectorRequirement> matchExpressions, final SubmitApplicationRequest request) {
    if (request == null || request.getSparkConf() == null || !request.getSparkConf().containsKey(CONFIG_PICKED_ZONES) || request.getSparkConf().get(CONFIG_PICKED_ZONES) == null || request.getSparkConf().get(CONFIG_PICKED_ZONES).isEmpty()) {
        return;
    }
    String[] pickedZone = request.getSparkConf().get(CONFIG_PICKED_ZONES).split(PICKED_ZONES_DELIMITER);
    if (pickedZone.length == 0) {
        return;
    }
    matchExpressions.add(new NodeSelectorRequirement(K8S_ZONE_LABEL, NodeSelectorOperator.NodeSelectorOpIn.toString(), pickedZone));
}
